const e="ema-youth-festival",u=2025,t="Built from the EMA Youth Festival Event Rules page and the 2025 event page (both read in full). The dates, venue and deadlines are from 2025 and are the starting values for the next edition. The audio-track dates (May 4th, April 30th) are printed without a year. The rules page lists Recitation, Elocution and Story Telling once for each of Malayalam and English; the template has one item for each, so the rule rows cover both. Not printed: a minimum age, a points scale for ranks or prizes, prize details, a points total (each criteria set adds to 100), a rain or cancellation policy, a contact person or phone number. The page's 'Event Categories' (Dance, Speech & Performance, Music) are the template's categories.",n={Title:"Rules & Criteria",Subtitle:"EMA Youth Festival. Read the rules before you register.",NoticeTitle:"Please Read Before Registering",Notice:"The festival is on {{EventDate}} at {{Venue}}. Register by {{RegistrationDeadline}} and pay by {{PaymentDeadline}}. Audio tracks must be shared by {{AudioTrackDeadline}} (dance and fancy dress) or {{KaraokeDeadline}} (film song and western music). It is open to all youth under 18 years of age.",Notes:["All participants must keep to the time limits, the event guidelines and the code of conduct.","After the registration closes, the schedule is sent to participants by email.","Registration fee: {{RegistrationFee}}."],Sections:[{Key:"general",Title:"General Rules",Items:["Every participant gets a unique registration number. It is used to announce their identity to the judges.","The name of the participant, teacher (guru) or choreographer must not be announced. It can lead to disqualification.","All events are solo events done by one person, except Group Dance.","Only the participant is allowed on stage. The organising team gives any help needed to set up or clean up.","Any materials brought to the stage must be cleared and removed from the stage and from the event premises on completion of the performance and before 6 PM.","When you take photographs or videos of the events, do not block the judges.","Participants and their families are responsible for any properties, costumes and instruments used for the performance. EMA is not responsible for any loss of property."]},{Key:"eligibility",Title:"Eligibility",Items:["The festival is open to all youth under 18 years of age.","No minimum age is printed.","Group Dance needs at least 3 participants.","In Group Dance, if a group has participants from different age groups, the team competes in the age group of the oldest participant.","Each participant must sign up separately for Group Dance."]},{Key:"registration",Title:"How to Register",Items:["Register for each event you want to enter by {{RegistrationDeadline}}.","Pay the registration fee by {{PaymentDeadline}}.","Share the audio track by {{AudioTrackDeadline}} for Bharatanatyam, Cinematic/Fusion/Western Dance, Group Dance and the fancy dress background track.","Share the karaoke or track by {{KaraokeDeadline}} for Film Song and Western Music.","Elocution topics are published a week before the competition.","Review the complete rules before you register.","After registration closes, you get the schedule by email."]},{Key:"fees",Title:"Fees",Items:["Registration fee: {{RegistrationFee}}.","The fee is per event. Pay by {{PaymentDeadline}}."]},{Key:"dates",Title:"Important Dates",Items:["Festival date: {{EventDate}}.","Registration deadline: {{RegistrationDeadline}}.","Payment deadline: {{PaymentDeadline}}.","Audio tracks for Bharatanatyam, Cinematic/Fusion/Western Dance, Group Dance and Fancy Dress: {{AudioTrackDeadline}}.","Karaoke or track for Film Song and Western Music: {{KaraokeDeadline}}.","Elocution topics: published a week before the competition."]},{Key:"venue",Title:"Venue",Items:["The festival is held at {{Venue}}.","The venue changed because of administrative challenges at the school district. The new location is about 2 miles from the old location."]},{Key:"conduct",Title:"Time Limits and Conduct",Items:["Keep to the time limit for each event. Going over the time limit leads to disqualification.","Participants get visual and/or audible warning signals before the time limit. In elocution and story telling, you must stop when the time limit bell rings."]},{Key:"judging",Title:"Judging",Items:["Each event is judged by criteria with points. They are listed under each competition."]}],Documents:[{Title:"EMA Youth Festival Event Rules and Judgement Criteria",Url:"https://www.extonmalayali.org/ema-youth-festival-event-rules/"},{Title:"2025 EMA Youth Festival event page",Url:"https://www.extonmalayali.org/event/2025-ema-youth-festival/"}]},i=[],a=[],o=JSON.parse('[{"Title":"Bharatanatyam","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Bharatanatyam","Sections":{"About":null,"TimeAndFormat":["Time limit: 5 minutes."],"Rules":["Share the audio track by {{AudioTrackDeadline}}."],"Allowed":null,"NotAllowed":["Participants are not allowed to make any announcements."],"Judging":["Aangika Abhinaya: 30 points.","Vaachika Abhinaya: 10 points.","Aahaarya Abhinaya: 10 points.","Saatvika Abhinaya: 20 points.","Taal and Laya: 20 points.","Space Usage and Presentation: 10 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## Time and format\\n- Time limit: 5 minutes.\\n\\n## Rules\\n- Share the audio track by {{AudioTrackDeadline}}.\\n\\n## Not allowed\\n- Participants are not allowed to make any announcements.\\n\\n## Judging\\n- Aangika Abhinaya: 30 points.\\n- Vaachika Abhinaya: 10 points.\\n- Aahaarya Abhinaya: 10 points.\\n- Saatvika Abhinaya: 20 points.\\n- Taal and Laya: 20 points.\\n- Space Usage and Presentation: 10 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Cinematic/Fusion/Western Dance","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Cinematic/Fusion/Western Dance","Sections":{"About":null,"TimeAndFormat":["Time limit: 5 minutes."],"Rules":["Share the audio track by {{AudioTrackDeadline}}.","EMA is not responsible for any loss of stage properties."],"Allowed":null,"NotAllowed":["Participants are not allowed to make any announcements."],"Judging":["Choreography: 40 points.","Steps, Transitions, Originality, Movement Techniques, Fluidity, Music Quality, Interpretation of Music and Finesse: 30 points.","Expression, Grace, Energy and Completeness of the Steps, Costume and Prop Usage: 20 points.","Overall Presentation: 10 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## Time and format\\n- Time limit: 5 minutes.\\n\\n## Rules\\n- Share the audio track by {{AudioTrackDeadline}}.\\n- EMA is not responsible for any loss of stage properties.\\n\\n## Not allowed\\n- Participants are not allowed to make any announcements.\\n\\n## Judging\\n- Choreography: 40 points.\\n- Steps, Transitions, Originality, Movement Techniques, Fluidity, Music Quality, Interpretation of Music and Finesse: 30 points.\\n- Expression, Grace, Energy and Completeness of the Steps, Costume and Prop Usage: 20 points.\\n- Overall Presentation: 10 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Group Dance","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Group Dance (Min 3 Participants)","Sections":{"About":null,"TimeAndFormat":["Time limit: 5 minutes."],"Rules":["A minimum of 3 participants is needed for this competition.","Share the audio track by {{AudioTrackDeadline}}.","If a group has participants from different age groups, the team competes in the age group of the oldest participant.","Each participant must sign up separately for the event."],"Allowed":null,"NotAllowed":null,"Judging":["Choreography: 40 points.","Steps, Transitions, Originality, Movement Techniques, Fluidity, Music Quality, Interpretation of Music and Finesse: 30 points.","Expression, Grace, Energy and Completeness of the Steps, Costume and Prop Usage: 20 points.","Overall Presentation: 10 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## Time and format\\n- Time limit: 5 minutes.\\n\\n## Rules\\n- A minimum of 3 participants is needed for this competition.\\n- Share the audio track by {{AudioTrackDeadline}}.\\n- If a group has participants from different age groups, the team competes in the age group of the oldest participant.\\n- Each participant must sign up separately for the event.\\n\\n## Judging\\n- Choreography: 40 points.\\n- Steps, Transitions, Originality, Movement Techniques, Fluidity, Music Quality, Interpretation of Music and Finesse: 30 points.\\n- Expression, Grace, Energy and Completeness of the Steps, Costume and Prop Usage: 20 points.\\n- Overall Presentation: 10 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Carnatic Music","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Carnatic Music","Sections":{"About":null,"TimeAndFormat":["Time limit: 5 minutes."],"Rules":null,"Allowed":["Participants can use a Shruti Box."],"NotAllowed":null,"Judging":["Raga (Melody): 25 points.","Tala (Rhythm): 25 points.","Bhava (Expression): 25 points.","Composition: 15 points.","Overall Impression: 10 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## Time and format\\n- Time limit: 5 minutes.\\n\\n## Allowed\\n- Participants can use a Shruti Box.\\n\\n## Judging\\n- Raga (Melody): 25 points.\\n- Tala (Rhythm): 25 points.\\n- Bhava (Expression): 25 points.\\n- Composition: 15 points.\\n- Overall Impression: 10 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Light Music","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Light Music (Malayalam)","Sections":{"About":["Light Music is in Malayalam."],"TimeAndFormat":["Time limit: 5 minutes."],"Rules":["The song language must be Malayalam.","Only non-film songs are allowed."],"Allowed":null,"NotAllowed":["Performing a film song leads to disqualification.","Accompanying instruments and karaoke are not allowed."],"Judging":["Swaram: 20 points.","Sruthilayam: 20 points.","Rhythm: 20 points.","Bhavam: 20 points.","Literary Clarity: 20 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## About this competition\\n- Light Music is in Malayalam.\\n\\n## Time and format\\n- Time limit: 5 minutes.\\n\\n## Rules\\n- The song language must be Malayalam.\\n- Only non-film songs are allowed.\\n\\n## Not allowed\\n- Performing a film song leads to disqualification.\\n- Accompanying instruments and karaoke are not allowed.\\n\\n## Judging\\n- Swaram: 20 points.\\n- Sruthilayam: 20 points.\\n- Rhythm: 20 points.\\n- Bhavam: 20 points.\\n- Literary Clarity: 20 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Film Song","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Film Song (Malayalam)","Sections":{"About":["Film Song is in Malayalam."],"TimeAndFormat":["Time limit: 5 minutes."],"Rules":["The song language must be Malayalam.","Share the karaoke by {{KaraokeDeadline}}."],"Allowed":["Karaoke is allowed."],"NotAllowed":null,"Judging":["Swaram: 20 points.","Sruthilayam: 20 points.","Rhythm: 20 points.","Bhavam: 20 points.","Literary Clarity: 20 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## About this competition\\n- Film Song is in Malayalam.\\n\\n## Time and format\\n- Time limit: 5 minutes.\\n\\n## Rules\\n- The song language must be Malayalam.\\n- Share the karaoke by {{KaraokeDeadline}}.\\n\\n## Allowed\\n- Karaoke is allowed.\\n\\n## Judging\\n- Swaram: 20 points.\\n- Sruthilayam: 20 points.\\n- Rhythm: 20 points.\\n- Bhavam: 20 points.\\n- Literary Clarity: 20 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Western Music","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Western Music","Sections":{"About":null,"TimeAndFormat":["Time limit: 5 minutes."],"Rules":["The performance must be in English.","Share the karaoke track by {{KaraokeDeadline}}."],"Allowed":["Karaoke is allowed."],"NotAllowed":["Accompanying instruments are not allowed."],"Judging":["Rhythm and Beat: 20 points.","Selection of Song: 20 points.","Voice Quality: 20 points.","Accent: 20 points.","Variation and Overall Impact: 20 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## Time and format\\n- Time limit: 5 minutes.\\n\\n## Rules\\n- The performance must be in English.\\n- Share the karaoke track by {{KaraokeDeadline}}.\\n\\n## Allowed\\n- Karaoke is allowed.\\n\\n## Not allowed\\n- Accompanying instruments are not allowed.\\n\\n## Judging\\n- Rhythm and Beat: 20 points.\\n- Selection of Song: 20 points.\\n- Voice Quality: 20 points.\\n- Accent: 20 points.\\n- Variation and Overall Impact: 20 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Instruments (String or Wind)","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Instruments (String or Wind)","Sections":{"About":null,"TimeAndFormat":["Time limit: 5 minutes."],"Rules":["Participants can perform on only one instrument, either string or wind."],"Allowed":null,"NotAllowed":["Other accompanying instruments, records, tracks and karaoke are not allowed."],"Judging":["Rhythm and Timing: 15 points.","Creativity: 15 points.","Authenticity and Perfection: 30 points.","Expression: 20 points.","Execution: 20 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## Time and format\\n- Time limit: 5 minutes.\\n\\n## Rules\\n- Participants can perform on only one instrument, either string or wind.\\n\\n## Not allowed\\n- Other accompanying instruments, records, tracks and karaoke are not allowed.\\n\\n## Judging\\n- Rhythm and Timing: 15 points.\\n- Creativity: 15 points.\\n- Authenticity and Perfection: 30 points.\\n- Expression: 20 points.\\n- Execution: 20 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Recitation","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Recitation Malayalam and Recitation English","Sections":{"About":["Recitation is held as two separate competitions: Recitation Malayalam and Recitation English."],"TimeAndFormat":["Time limit: 5 minutes. The timer starts when the participant begins the recitation."],"Rules":["Participants must recite poetry by a poet of their choice, Malayalam poetry in Recitation Malayalam and English poetry in Recitation English.","The participant can announce the name of the poem and the poet at the start of the performance.","Participants must recite the poem without written aids."],"Allowed":null,"NotAllowed":["Records, tracks and karaoke are not allowed."],"Judging":["Voice and Articulation: 30 points.","Expression of Emotion: 30 points.","Memorization: 20 points.","Overall Performance: 20 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## About this competition\\n- Recitation is held as two separate competitions: Recitation Malayalam and Recitation English.\\n\\n## Time and format\\n- Time limit: 5 minutes. The timer starts when the participant begins the recitation.\\n\\n## Rules\\n- Participants must recite poetry by a poet of their choice, Malayalam poetry in Recitation Malayalam and English poetry in Recitation English.\\n- The participant can announce the name of the poem and the poet at the start of the performance.\\n- Participants must recite the poem without written aids.\\n\\n## Not allowed\\n- Records, tracks and karaoke are not allowed.\\n\\n## Judging\\n- Voice and Articulation: 30 points.\\n- Expression of Emotion: 30 points.\\n- Memorization: 20 points.\\n- Overall Performance: 20 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Elocution","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Elocution Malayalam and Elocution English","Sections":{"About":["Elocution is held as two separate competitions: Elocution Malayalam and Elocution English."],"TimeAndFormat":["Time limit: 5 minutes. You must stop when the time limit bell rings."],"Rules":["Participants must perform only in Malayalam (Elocution Malayalam) or only in English (Elocution English).","The topic is published a week before the competition.","Participants must perform the elocution without written aids.","Participants must keep to the time limit."],"Allowed":null,"NotAllowed":null,"Judging":["Idea/Knowledge: 20 points.","Clarity: 20 points.","Voice Modulation: 20 points.","Confidence on Stage: 20 points.","Fluency: 20 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## About this competition\\n- Elocution is held as two separate competitions: Elocution Malayalam and Elocution English.\\n\\n## Time and format\\n- Time limit: 5 minutes. You must stop when the time limit bell rings.\\n\\n## Rules\\n- Participants must perform only in Malayalam (Elocution Malayalam) or only in English (Elocution English).\\n- The topic is published a week before the competition.\\n- Participants must perform the elocution without written aids.\\n- Participants must keep to the time limit.\\n\\n## Judging\\n- Idea/Knowledge: 20 points.\\n- Clarity: 20 points.\\n- Voice Modulation: 20 points.\\n- Confidence on Stage: 20 points.\\n- Fluency: 20 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Story Telling","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Story Telling Malayalam and Story Telling English","Sections":{"About":["Story Telling is held as two separate competitions: Malayalam and English."],"TimeAndFormat":["Time limit: 5 minutes. You must stop when the time limit bell rings."],"Rules":["Stories can be authentic, adapted or originally written.","Participants must perform only in Malayalam (Story Telling Malayalam) or only in English (Story Telling English).","Participants must perform the story telling without written aids."],"Allowed":null,"NotAllowed":null,"Judging":["Pronunciation: 20 points.","Fluency (Pace, Voice Quality, Vocal Expression): 20 points.","Performance (Confidence, Gesture, Mimicry): 20 points.","Creativity: 20 points.","Time Management: 20 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## About this competition\\n- Story Telling is held as two separate competitions: Malayalam and English.\\n\\n## Time and format\\n- Time limit: 5 minutes. You must stop when the time limit bell rings.\\n\\n## Rules\\n- Stories can be authentic, adapted or originally written.\\n- Participants must perform only in Malayalam (Story Telling Malayalam) or only in English (Story Telling English).\\n- Participants must perform the story telling without written aids.\\n\\n## Judging\\n- Pronunciation: 20 points.\\n- Fluency (Pace, Voice Quality, Vocal Expression): 20 points.\\n- Performance (Confidence, Gesture, Mimicry): 20 points.\\n- Creativity: 20 points.\\n- Time Management: 20 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Mono Act","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Mono Act","Sections":{"About":null,"TimeAndFormat":["Time limit: 5 minutes."],"Rules":["Participants can choose their own theme, topic or subject."],"Allowed":["Participants can use any supplementary items to perform the act in the best way. Participants must arrange these themselves."],"NotAllowed":["Records, audio tracks and karaoke are not allowed."],"Judging":["Acting Skills: 20 points.","Script: 20 points.","Dialogue Delivery: 20 points.","Presentation: 20 points.","Time Management: 20 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## Time and format\\n- Time limit: 5 minutes.\\n\\n## Rules\\n- Participants can choose their own theme, topic or subject.\\n\\n## Allowed\\n- Participants can use any supplementary items to perform the act in the best way. Participants must arrange these themselves.\\n\\n## Not allowed\\n- Records, audio tracks and karaoke are not allowed.\\n\\n## Judging\\n- Acting Skills: 20 points.\\n- Script: 20 points.\\n- Dialogue Delivery: 20 points.\\n- Presentation: 20 points.\\n- Time Management: 20 points.\\n\\n## Points\\n- Total 100 points."},{"Title":"Fancy Dress","Source":"EMA Youth Festival Event Rules & Judgement Criteria page, Fancy Dress","Sections":{"About":null,"TimeAndFormat":["Time limit: 3 minutes."],"Rules":["Participants can choose their own theme, topic or subject.","Share the background track by {{AudioTrackDeadline}}."],"Allowed":["Participants can use any supplementary items to perform the act in the best way. Participants must arrange these themselves.","A background track is allowed."],"NotAllowed":null,"Judging":["Costume: 20 points.","Theme Adherence: 20 points.","Expression and Gestures: 20 points.","Novelty (new ideas): 20 points.","Overall Impression: 20 points."],"Points":["Total 100 points."],"Notes":null},"Markdown":"## Time and format\\n- Time limit: 3 minutes.\\n\\n## Rules\\n- Participants can choose their own theme, topic or subject.\\n- Share the background track by {{AudioTrackDeadline}}.\\n\\n## Allowed\\n- Participants can use any supplementary items to perform the act in the best way. Participants must arrange these themselves.\\n- A background track is allowed.\\n\\n## Judging\\n- Costume: 20 points.\\n- Theme Adherence: 20 points.\\n- Expression and Gestures: 20 points.\\n- Novelty (new ideas): 20 points.\\n- Overall Impression: 20 points.\\n\\n## Points\\n- Total 100 points."}]'),s=[],l=[{Key:"EventDate",Kind:"date",Label:"Festival date",Value:"2025-05-10",Source:"2025 EMA Youth Festival event page, Event Highlights"},{Key:"Venue",Kind:"address",Label:"Festival venue",Value:{Name:"Uwchlan Hills Elementary School",Address:"50 Peck Rd",City:"Downingtown, PA 19335",MapUrl:"",Directions:"The venue changed to this school, about 2 miles from the old location."},Source:"2025 EMA Youth Festival event page, Event Highlights and Venue Update"},{Key:"RegistrationDeadline",Kind:"date",Label:"Registration deadline",Value:"2025-04-20",Source:"2025 EMA Youth Festival event page"},{Key:"PaymentDeadline",Kind:"date",Label:"Payment deadline",Value:"2025-05-04",Source:"2025 EMA Youth Festival event page"},{Key:"AudioTrackDeadline",Kind:"date",Label:"Deadline to share audio tracks (dance and fancy dress)",Value:"May 4th",Source:"EMA Youth Festival Event Rules & Judgement Criteria page, Bharatanatyam, Cinematic/Fusion/Western Dance, Group Dance, Fancy Dress"},{Key:"KaraokeDeadline",Kind:"date",Label:"Deadline to share karaoke (Film Song and Western Music)",Value:"April 30th",Source:"EMA Youth Festival Event Rules & Judgement Criteria page, Film Song and Western Music"},{Key:"RegistrationFee",Kind:"fee",Label:"Registration fee per event",Value:"$10 per event for EMA members, $20 per event for non-members",Source:"2025 EMA Youth Festival event page, Registration Fees"},{Key:"Announcements",Kind:"news",Label:"News printed on the event page",Value:[{Date:"",Title:"Venue update",Text:"Due to administrative challenges at the school district, the venue changed. The new location is only 2 miles away from the old location.",Url:""},{Date:"",Title:"Registrations closed",Text:"Registrations are closed. Keep an eye out for the schedule in your email.",Url:""}],Source:"2025 EMA Youth Festival event page"}],r=[{Claim:"Event rules, time limits, deadlines and judging criteria for every event.",SourceType:"Primary - Exton Malayali Association (EMA) official Youth Festival Event Rules page",Source:"EMA Youth Festival - Event Rules & Judgement Criteria",Url:"https://www.extonmalayali.org/ema-youth-festival-event-rules/"},{Claim:"Date, venue, eligibility, deadlines, fees and categories for the 2025 festival.",SourceType:"Primary - Exton Malayali Association (EMA) official event page",Source:"2025 EMA Youth Festival",Url:"https://www.extonmalayali.org/event/2025-ema-youth-festival/"}],m={TemplateKey:e,Year:2025,Note:t,Page:n,ParticipantTypes:i,AgeGroups:a,Competitions:o,CompetitionAgeGroups:s,Variables:l,Evidence:r};export{a as AgeGroups,s as CompetitionAgeGroups,o as Competitions,r as Evidence,t as Note,n as Page,i as ParticipantTypes,e as TemplateKey,l as Variables,u as Year,m as default};
